import React, { useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, Modal, TextInput, FlatList, Image, ScrollView, StyleSheet, Alert } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as ImagePicker from 'expo-image-picker';
import { collection, query, where, orderBy, onSnapshot, addDoc, doc, getDoc, getDocs, updateDoc, deleteDoc, arrayUnion, arrayRemove, serverTimestamp } from 'firebase/firestore';
import { auth, db } from '../config';
import { useTheme, BRAND } from './theme';

const QUICK_EMOJIS = ['❤️', '🙌', '🔥', '👏', '😢', '😍', '😮', '😂'];
const CLOUD_NAME = 'faqfo0lu';
const UPLOAD_PRESET = 'flevora_upload';

export function CommentModal({ postId, onClose }: { postId: string | null; onClose: () => void }) {
  const { c } = useTheme();
    const [comments, setComments] = useState<any[]>([]);
      const [text, setText] = useState('');
        const [replyTo, setReplyTo] = useState<string | null>(null);
          const [editId, setEditId] = useState<string | null>(null);
            const myUid = auth.currentUser?.uid;

              useEffect(() => {
                  if (!postId) { setComments([]); return; }
                      return onSnapshot(query(collection(db, 'posts', postId, 'comments'), orderBy('createdAt', 'asc')), (s) => {
                            setComments(s.docs.map((d) => ({ id: d.id, ...d.data() })));
                                }, () => {});
                                  }, [postId]);

                                    const toggleLike = (item: any) => {
                                        if (!postId || !myUid) return;
                                            const liked = (item.likes || []).includes(myUid);
                                                updateDoc(doc(db, 'posts', postId, 'comments', item.id), { likes: liked ? arrayRemove(myUid) : arrayUnion(myUid) }).catch(() => {});
                                                  };

                                                    const onHoldComment = (item: any) => {
                                                        if (!postId || item.uid !== myUid) return;
                                                            Alert.alert('Your Comment', 'Choose an action:', [
                                                                  { text: 'Edit', onPress: () => { setEditId(item.id); setText(item.text || ''); } },
                                                                        { text: 'Delete', style: 'destructive', onPress: () => deleteDoc(doc(db, 'posts', postId, 'comments', item.id)) },
                                                                              { text: 'Cancel', style: 'cancel' },
                                                                                  ]);
                                                                                    };

                                                                                      const sendImageComment = async () => {
                                                                                          if (!postId || !myUid) return;
                                                                                              const res = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], quality: 0.7 });
                                                                                                  if (res.canceled || !res.assets[0]) return;
                                                                                                      const data = new FormData();
                                                                                                          data.append('file', { uri: res.assets[0].uri, type: 'image/jpeg', name: `cmt_${Date.now()}.jpg` } as any);
                                                                                                              data.append('upload_preset', UPLOAD_PRESET);
                                                                                                                  const up = await fetch(`https://api.cloudinary.com/v1_1/${CLOUD_NAME}/image/upload`, { method: 'POST', body: data });
                                                                                                                      const json = await up.json();
                                                                                                                          if (!json.secure_url) return;
                                                                                                                              const u = await getDoc(doc(db, 'users', myUid));
                                                                                                                                  await addDoc(collection(db, 'posts', postId, 'comments'), {
                                                                                                                                        uid: myUid, username: u.data()?.username || 'user', text: '', imageUrl: json.secure_url, likes: [], createdAt: serverTimestamp(),
                                                                                                                                            });
                                                                                                                                              };

                                                                                                                                                const send = async (overrideTxt?: string) => {
                                                                                                                                                    const raw = (overrideTxt ?? text).trim();
                                                                                                                                                        if (!postId || !raw || !myUid) return;
                                                                                                                                                            setText(''); setReplyTo(null);
                                                                                                                                                                if (editId) {
                                                                                                                                                                      await updateDoc(doc(db, 'posts', postId, 'comments', editId), { text: raw });
                                                                                                                                                                            setEditId(null); return;
                                                                                                                                                                                }
                                                                                                                                                                                    const u = await getDoc(doc(db, 'users', myUid));
                                                                                                                                                                                        const uname = u.data()?.username || 'user';
                                                                                                                                                                                            await addDoc(collection(db, 'posts', postId, 'comments'), { uid: myUid, username: uname, text: raw, likes: [], createdAt: serverTimestamp() });
                                                                                                                                                                                                const postSnap = await getDoc(doc(db, 'posts', postId));
                                                                                                                                                                                                    const ownerUid = postSnap.data()?.uid;
                                                                                                                                                                                                        if (ownerUid && ownerUid !== myUid) {
                                                                                                                                                                                                              await addDoc(collection(db, 'notifications'), {
                                                                                                                                                                                                                      toUid: ownerUid, fromUid: myUid, fromUsername: uname, type: 'comment', message: `commented: ${raw}`, read: false, createdAt: serverTimestamp(),
                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                    for (const m of (raw.match(/@\w+/g) || [])) {
                                                                                                                                                                                                                                          const snap = await getDocs(query(collection(db, 'users'), where('username', '==', m.slice(1).toLowerCase())));
                                                                                                                                                                                                                                                snap.forEach((ds) => {
                                                                                                                                                                                                                                                        if (ds.id !== myUid) {
                                                                                                                                                                                                                                                                  addDoc(collection(db, 'notifications'), { toUid: ds.id, fromUid: myUid, fromUsername: uname, type: 'mention', message: `mentioned you: ${raw}`, read: false, createdAt: serverTimestamp() });
                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                            <Modal visible={!!postId} animationType="slide" transparent>
                                                                                                                                                                                                                                                                                                  <View style={styles.cBg}>
                                                                                                                                                                                                                                                                                                          <View style={[styles.cCard, { backgroundColor: c.background }]}>
                                                                                                                                                                                                                                                                                                                    <View style={[styles.cHead, { borderBottomColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                <Text style={{ color: c.text, fontWeight: '700', fontSize: 16 }}>Comments ({comments.length})</Text>
                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity hitSlop={12} onPress={onClose}><Ionicons name="close" size={24} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                      </View>
                                                                                                                                                                                                                                                                                                                                                                <FlatList
                                                                                                                                                                                                                                                                                                                                                                            style={{ flex: 1 }} data={comments} keyExtractor={(i) => i.id}
                                                                                                                                                                                                                                                                                                                                                                                        ListEmptyComponent={<Text style={{ color: c.muted, textAlign: 'center', marginTop: 32 }}>No comments yet. Be the first!</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                    renderItem={({ item }) => {
                                                                                                                                                                                                                                                                                                                                                                                                                  const likes: string[] = item.likes || [];
                                                                                                                                                                                                                                                                                                                                                                                                                                const liked = myUid ? likes.includes(myUid) : false;
                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity activeOpacity={0.8} onLongPress={() => onHoldComment(item)} style={styles.row}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <View style={{ flex: 1 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Text style={{ color: c.text }}><Text style={{ fontWeight: '700' }}>@{item.username} </Text>{item.text}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {!!item.imageUrl && <Image source={{ uri: item.imageUrl }} style={styles.cImg} />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity onPress={() => { setReplyTo(item.username); setText(`@${item.username} `); }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={{ color: c.muted, fontSize: 12, fontWeight: '600', marginTop: 3 }}>Reply</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity onPress={() => toggleLike(item)} style={styles.likeBtn}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Ionicons name={liked ? 'heart' : 'heart-outline'} size={17} color={liked ? '#EF4444' : c.muted} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {likes.length > 0 && <Text style={{ color: c.muted, fontSize: 11 }}>{likes.length}</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ maxHeight: 38, marginVertical: 4 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {QUICK_EMOJIS.map((e) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <TouchableOpacity key={e} onPress={() => setText((prev) => prev + e)} style={{ marginRight: 16 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Text style={{ fontSize: 22 }}>{e}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </ScrollView>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {(replyTo || editId) && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <View style={styles.replyBar}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <Text style={{ color: c.muted, fontSize: 12 }}>{editId ? 'Editing comment' : `Replying to @${replyTo}`}</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity onPress={() => { setReplyTo(null); setEditId(null); setText(''); }}><Text style={{ color: BRAND, fontSize: 12, fontWeight: '700' }}>Cancel</Text></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={[styles.cInputRow, { borderTopColor: c.border }]}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TextInput style={[styles.cInput, { backgroundColor: c.input, color: c.text }]} placeholder="Add a comment..." placeholderTextColor={c.muted} value={text} onChangeText={setText} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity onPress={sendImageComment}><Ionicons name="image-outline" size={22} color={c.text} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <TouchableOpacity onPress={() => send('🎁✨ Super Gift!')}><Ionicons name="gift-outline" size={21} color={BRAND} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity onPress={() => send()}><Ionicons name="send" size={22} color={BRAND} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cBg: { flex: 1, backgroundColor: 'rgba(0,0,0,0.45)', justifyContent: 'flex-end' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cCard: { height: '68%', borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cHead: { flexDirection: 'row', justifyContent: 'space-between', paddingBottom: 10, borderBottomWidth: 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        row: { flexDirection: 'row', alignItems: 'center', paddingVertical: 8, gap: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          cImg: { width: 140, height: 140, borderRadius: 10, marginTop: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            likeBtn: { alignItems: 'center', minWidth: 28 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              replyBar: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 4 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cInputRow: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingTop: 10, borderTopWidth: 1 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cInput: { flex: 1, borderRadius: 20, paddingHorizontal: 14, paddingVertical: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  